import {predict,windowFor,windowComplete,aggregateMonthly,validateRow,parseCSV,makeCSV,SEASONS} from './model.js';
const $=id=>document.getElementById(id),fmt=(v,d=2)=>v==null||!Number.isFinite(+v)?'—':new Intl.NumberFormat('vi-VN',{minimumFractionDigits:d,maximumFractionDigits:d}).format(+v);
let model,history,provinces,comparison,uploaded=[],lastResult=null,apiUrl='',requestId=0,activeFetch=null;
const labels={adm1_code:'Mã tỉnh',nam:'Năm mùa vụ',mua_vu:'Nhóm vụ',temperature_mean_c:'Nhiệt độ trung bình (°C)',temperature_min_c:'Nhiệt độ tháng thấp nhất (°C)',temperature_max_c:'Nhiệt độ tháng cao nhất (°C)',rainfall_sum_mm:'Tổng lượng mưa (mm)',rainfall_max_month_mm:'Mưa tháng cao nhất (mm)',rainy_months_100mm:'Tháng có mưa ≥ 100 mm',ndvi_mean:'NDVI trung bình',ndvi_max:'NDVI cao nhất',evi_mean:'EVI trung bình',evi_max:'EVI cao nhất',vci_mean:'VCI trung bình',vci_min:'VCI thấp nhất',vi_months_available:'Số tháng có dữ liệu VI',vi_months_quality80:'Tháng đạt chất lượng ≥ 80%',vi_quality80_ratio:'Tỷ lệ tháng đạt chất lượng',vi_mean_coverage_pct:'Độ phủ pixel trung bình (%)'};
function selection(){return {code:$('province').value,year:+$('year').value,season:$('season').value};}
function provinceName(code){return provinces.find(p=>String(p.adm1_code)===String(code))?.tinh_thanh||String(code);}
function download(name,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function showView(view){$('estimate-view').hidden=view!=='estimate';$('models-view').hidden=view!=='models';$('breadcrumb-current').textContent=view==='estimate'?'Ước lượng':'Đối chiếu mô hình';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function clearResult(){activeFetch?.abort();activeFetch=null;requestId++;$('estimate-button').disabled=false;$('estimate-button').innerHTML='Ước lượng năng suất <span>↗</span>';lastResult=null;$('download-result').disabled=true;$('result-card').classList.add('error-state');$('yield-value').textContent='—';$('actual-value').textContent='—';$('error-value').textContent='—';$('result-location').textContent='Sẵn sàng cho mùa vụ mới';$('result-season').textContent='Chọn dữ liệu và nhấn Ước lượng năng suất';$('result-source').textContent='Chưa tính';for(const id of ['env-temp','env-rain','env-ndvi','env-quality'])$(id).textContent='—';$('trend-chart').replaceChildren();$('features-table').querySelector('tbody').replaceChildren();$('result-notice').hidden=true;}
function setMode(mode){$('mode-history').classList.toggle('selected',mode==='history');$('mode-new').classList.toggle('selected',mode==='new');$('source').value=mode==='history'?'history':(uploaded.length?'upload':'gee');$('year').value=mode==='history'?'2022':String(new Date().getFullYear());updateForm();clearResult();}
function updateForm(){const {year,season}=selection(),w=windowFor(year,season);$('window-label').textContent=`${w.start.slice(5)}/${w.start.slice(0,4)} — ${w.end.slice(5)}/${w.end.slice(0,4)}`;$('window-subtitle').textContent=`${w.months.length} tháng · ${windowComplete(year,season)?'Cửa sổ đã kết thúc':'Cửa sổ chưa kết thúc'}`;const source=$('source').value;$('upload-controls').hidden=source!=='upload';$('gee-controls').hidden=source!=='gee';$('form-message').textContent=!windowComplete(year,season)?`Cần quan sát hết tháng ${w.end.slice(5)}/${year}. Không ước lượng cả vụ bằng dữ liệu chưa hoàn tất.`:(source==='history'&&year>2022?'Bộ dữ liệu hiện có đến 2022. Hãy chọn CSV hoặc GEE cho năm mới.':'');}
function renderChart(code,season){const rows=history.filter(r=>String(r.adm1_code)===String(code)&&r.mua_vu===season).sort((a,b)=>a.nam-b.nam);if(!rows.length)return;const width=640,height=180,left=30,right=16,top=12,bottom=28;const predictions=rows.map(r=>predict(model,r)),all=[...rows.map(r=>r.nang_suat_t_ha),...predictions],lo=Math.floor(Math.min(...all)*2)/2-.2,hi=Math.ceil(Math.max(...all)*2)/2+.2;const x=y=>left+(y-2000)/22*(width-left-right),y=v=>height-bottom-(v-lo)/(hi-lo)*(height-top-bottom);const line=values=>values.map((v,i)=>`${i?'L':'M'}${x(rows[i].nam).toFixed(2)},${y(v).toFixed(2)}`).join(' ');let svg=`<svg viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg"><rect x="${x(2019)}" y="${top}" width="${x(2022)-x(2019)}" height="${height-top-bottom}" fill="#f5f6ed"/>`;for(let i=0;i<4;i++){let value=lo+(hi-lo)*i/3;svg+=`<line x1="${left}" y1="${y(value)}" x2="${width-right}" y2="${y(value)}" stroke="#e9eee3"/><text x="${left-8}" y="${y(value)+3}" text-anchor="end" fill="#9aa990" font-size="8">${fmt(value,1)}</text>`;}for(const year of [2000,2005,2010,2015,2022])svg+=`<text x="${x(year)}" y="${height-7}" text-anchor="middle" fill="#9aa990" font-size="8">${year}</text>`;svg+=`<path d="${line(rows.map(r=>r.nang_suat_t_ha))}" fill="none" stroke="#2c6046" stroke-width="2"/><path d="${line(predictions)}" fill="none" stroke="#bac998" stroke-width="2" stroke-dasharray="5 3"/>`;rows.forEach((r,i)=>{svg+=`<circle cx="${x(r.nam)}" cy="${y(r.nang_suat_t_ha)}" r="2.5" fill="#2c6046"><title>${r.nam}: thực tế ${fmt(r.nang_suat_t_ha)}; mô hình ${fmt(predictions[i])} tấn/ha</title></circle>`;});svg+='</svg>';$('trend-chart').innerHTML=svg;$('trend-chart').setAttribute('aria-label',`Năng suất ${provinceName(code)}, ${SEASONS[season]}, 2000–2022; đường liền là thực tế, đường đứt là dự đoán.`);}
function renderResult(row,sourceLabel,provenance){const value=predict(model,row);lastResult={row,value,source:sourceLabel,provenance};const actual=row.nang_suat_t_ha==null||row.nang_suat_t_ha===''?null:Number(row.nang_suat_t_ha);$('result-card').classList.remove('error-state');$('result-location').textContent=provinceName(row.adm1_code);$('result-season').textContent=`${SEASONS[row.mua_vu]} · ${row.nam}`;$('result-source').textContent=sourceLabel;$('yield-value').textContent=fmt(value);$('actual-value').textContent=actual!==null&&Number.isFinite(actual)?`${fmt(actual)} tấn/ha`:'Chưa có số liệu';$('error-value').textContent=actual!==null&&Number.isFinite(actual)?`${fmt(Math.abs(value-actual))} tấn/ha`:'Chưa thể đối chiếu';$('download-result').disabled=false;$('env-temp').textContent=`${fmt(row.temperature_mean_c,1)} °C`;$('env-rain').textContent=`${fmt(row.rainfall_sum_mm,0)} mm`;$('env-ndvi').textContent=fmt(row.ndvi_mean,3);const w=windowFor(+row.nam,row.mua_vu);$('env-quality').textContent=`${row.vi_months_quality80}/${w.months.length}`;const body=$('features-table').querySelector('tbody');body.replaceChildren();for(const key of model.feature_names){const tr=document.createElement('tr'),td1=document.createElement('td'),td2=document.createElement('td');td1.textContent=labels[key]||key;td2.textContent=row[key]==null?'Thiếu · dùng trung vị lịch sử':typeof row[key]==='number'?fmt(row[key],Number.isInteger(row[key])?0:4):String(row[key]);tr.append(td1,td2);body.append(tr);}let notes=[];if(+row.nam>2022)notes.push(`Năm ${row.nam} nằm ngoài giai đoạn đã đánh giá 2019–2022; cần kiểm chứng với số liệu thực tế.`);if(sourceLabel==='CSV nhập')notes.push('Dữ liệu do bạn cung cấp; ứng dụng chưa xác minh nguồn và quy trình tạo đặc trưng.');if(+row.vi_months_quality80===0)notes.push('Không có tháng vệ tinh đạt chất lượng; đặc trưng VI thiếu được điền bằng trung vị lịch sử.');if(+row.vi_months_quality80<w.months.length)notes.push(`Có ${row.vi_months_quality80}/${w.months.length} tháng vệ tinh đạt độ phủ ≥ 80%.`);if(value<=0||value<Math.min(...history.map(r=>r.nang_suat_t_ha))||value>Math.max(...history.map(r=>r.nang_suat_t_ha)))notes.push('Kết quả nằm ngoài khoảng năng suất trong bộ dữ liệu; cần kiểm tra đầu vào trước khi diễn giải.');$('result-notice').hidden=!notes.length;$('result-notice').textContent=notes.join(' ');renderChart(row.adm1_code,row.mua_vu);}
async function estimate(event){event?.preventDefault();const token=++requestId,{code,year,season}=selection(),button=$('estimate-button');$('form-message').textContent='';button.disabled=true;button.textContent='Đang xử lý dữ liệu…';try{if(!windowComplete(year,season))throw Error('Cửa sổ vụ chưa kết thúc. Chưa thể dùng mô hình cả vụ để dự báo sớm.');let row,source,provenance={};switch($('source').value){case 'history':row=history.find(r=>String(r.adm1_code)===code&&r.nam===year&&r.mua_vu===season);if(!row)throw Error('Chưa có bản ghi lịch sử cho lựa chọn này. Chọn CSV hoặc GEE để cung cấp dữ liệu mới.');source='CSV lịch sử';break;case 'upload':if(!uploaded.length)throw Error('Hãy chọn CSV trước khi ước lượng.');if('month' in uploaded[0])row=aggregateMonthly(uploaded,code,year,season);else{const rows=uploaded.filter(r=>String(Number(r.adm1_code))===code&&+r.nam===year&&r.mua_vu===season);if(rows.length!==1)throw Error('CSV cần đúng một dòng đặc trưng cho tỉnh, năm và vụ đã chọn.');row=rows[0];}source='CSV nhập';break;case 'gee':if(!apiUrl)throw Error('Chưa kết nối API GEE. Bạn có thể nhập CSV xuất từ GEE để kiểm nghiệm ngay.');$('form-message').textContent='Đang lấy dữ liệu GEE; việc thống kê vệ tinh có thể mất vài phút.';activeFetch=new AbortController();const response=await fetch(`${apiUrl}/v1/monthly`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adm1_code:+code,year,season}),signal:AbortSignal.any([activeFetch.signal,AbortSignal.timeout(240000)])});const result=await response.json();if(!response.ok)throw Error(result.detail||'API không lấy được dữ liệu.');if(result.provenance?.vci_baseline!=='2000-2015'||result.provenance?.rice_mask_year!==2020)throw Error('Chuẩn VCI hoặc mặt nạ của API không khớp mô hình.');row=aggregateMonthly(result.rows,code,year,season);source='GEE qua API';provenance=result.provenance;break;}
 if(token!==requestId)return;validateRow(model,row,provinces.map(p=>String(p.adm1_code)));const w=windowFor(year,season);if(row.window_start&&row.window_start!==w.start||row.window_end&&row.window_end!==w.end)throw Error('Cửa sổ CSV không khớp mùa vụ.');renderResult(row,source,provenance);$('form-message').textContent='';}catch(error){if(token===requestId){clearResult();$('form-message').textContent=error.name==='TimeoutError'?'API chưa trả kết quả trong thời gian chờ. Có thể xuất CSV từ GEE và nhập để tiếp tục.':error.message||'Không thể ước lượng với dữ liệu hiện tại.';}}finally{if(token===requestId){activeFetch=null;button.disabled=false;button.innerHTML='Ước lượng năng suất <span>↗</span>';}}}
function renderModels(){const tbody=$('model-table').querySelector('tbody');comparison.forEach(r=>{const tr=document.createElement('tr');if(r.selected_for_saving)tr.className='selected-model';for(const val of [r.model+(r.selected_for_saving?' · Được chọn':''),fmt(r.MAE_t_ha,4),fmt(r.RMSE_t_ha,4),fmt(r.R2,4),`${r.top3_appearances}/3`]){const td=document.createElement('td');td.textContent=val;tr.append(td);}tbody.append(tr);});for(const [metric,title,direction] of [['MAE_t_ha','MAE','Thấp hơn tốt hơn'],['RMSE_t_ha','RMSE','Thấp hơn tốt hơn'],['R2','R²','Cao hơn tốt hơn']]){const card=document.createElement('section');card.className='card';const heading=document.createElement('h2');heading.textContent=`Top 3 · ${title}`;const text=document.createElement('p');text.className='input-hint';text.textContent=direction;const list=document.createElement('ol');comparison.slice().sort((a,b)=>a[`rank_${metric}`]-b[`rank_${metric}`]).slice(0,3).forEach(r=>{const item=document.createElement('li');item.textContent=`${r.model} · ${fmt(r[metric],4)}`;list.append(item);});card.append(heading,text,list);$('top3-cards').append(card);}}
function openData(){$('data-dialog').showModal();}
async function connectAPI(){const raw=$('api-url').value.trim();$('api-message').textContent='Đang kiểm tra…';try{if(!raw)throw Error('Hãy nhập URL backend đã triển khai, hoặc dùng bản cục bộ với file JSON theo hướng dẫn bên dưới.');let url;try{url=new URL(raw);}catch{throw Error('Địa chỉ API chưa hợp lệ. Cần URL đầy đủ bắt đầu bằng https://.');}if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname)))throw Error('Dùng địa chỉ HTTPS; HTTP chỉ dành cho localhost.');url.pathname=url.pathname.replace(/\/$/,'');if(url.search||url.hash||url.username||url.password)throw Error('Địa chỉ API không chứa mật khẩu hoặc tham số bí mật.');const base=url.href.replace(/\/$/,'');const response=await fetch(`${base}/health`,{signal:AbortSignal.timeout(10000)}),body=await response.json();if(!response.ok||body.service!=='lua-lab-gee-api')throw Error('Endpoint chưa phải API dữ liệu Lúa Lab.');if(!body.gee_configured)throw Error('API đang chạy nhưng chưa cấu hình Project ID và Asset ID ở máy chủ.');apiUrl=base;$('api-message').textContent='Đã kết nối API. Quyền GEE và dữ liệu sẽ được kiểm tra khi thực hiện yêu cầu thật.';$('connection-text').textContent='API dữ liệu đã kết nối';$('connection-dot').classList.remove('muted');$('gee-info').textContent='API đã kết nối. Chưa kiểm tra quyền nguồn cho đến khi lấy dữ liệu vụ.';}catch(error){apiUrl='';$('api-message').textContent=error.name==='TimeoutError'?'API không phản hồi trong 10 giây.':error.message;$('connection-text').textContent='GEE chưa kết nối';$('connection-dot').classList.add('muted');}}
async function detectSameServerAPI(){
 try{
  const response=await fetch('/health',{signal:AbortSignal.timeout(2500)});
  if(!response.ok)return;
  const health=await response.json();
  if(health.service!=='lua-lab-gee-api'||!health.gee_configured)return;
  apiUrl=window.location.origin;
  $('api-url').value=apiUrl;
  $('connection-text').textContent='GEE cùng máy chủ đã cấu hình';
  $('connection-dot').classList.remove('muted');
  $('gee-info').textContent='Tự kết nối backend cùng máy chủ. Quyền nguồn sẽ được kiểm tra khi lấy dữ liệu thật.';
  $('api-message').textContent='Đã tự nhận backend. Không cần nhập địa chỉ API riêng; file JSON được giữ trên máy chủ.';
 }catch{/* Static hosted site: manual remote API or CSV is still available. */}
}
async function init(){try{const data=await Promise.all(['model','history','provinces','comparison'].map(async n=>{const r=await fetch(`./data/${n}.json`);if(!r.ok)throw Error('Không tải được mô hình hoặc dữ liệu.');return r.json();}));[model,history,provinces,comparison]=data;for(const p of provinces){const option=document.createElement('option');option.value=p.adm1_code;option.textContent=p.tinh_thanh;$('province').append(option);}$('province').value='3326';for(let year=new Date().getFullYear()+1;year>=2000;year--){const option=document.createElement('option');option.value=year;option.textContent=year;$('year').append(option);}$('year').value='2022';$('metric-mae').textContent=fmt(model.evaluation_metrics.MAE_t_ha,3);$('metric-rmse').textContent=fmt(model.evaluation_metrics.RMSE_t_ha,3);$('metric-r2').textContent=fmt(model.evaluation_metrics.R2,3);renderModels();updateForm();await estimate();await detectSameServerAPI();}catch(error){$('form-message').textContent=error.message;$('result-location').textContent='Chưa tải được dữ liệu';$('estimate-button').disabled=true;}}
$('estimate-form').addEventListener('submit',estimate);for(const id of ['province','year','season','source'])$(id).addEventListener('change',()=>{clearResult();if(model)updateForm();});$('mode-history').onclick=()=>setMode('history');$('mode-new').onclick=()=>setMode('new');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('about-model').onclick=()=>showView('models');for(const id of ['open-data','connection-shortcut','configure-api'])$(id).onclick=openData;$('close-data').onclick=()=>$('data-dialog').close();$('test-api').onclick=connectAPI;$('toggle-features').onclick=()=>{const open=$('features-panel').hidden;$('features-panel').hidden=!open;$('toggle-features').setAttribute('aria-expanded',String(open));};$('csv-file').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('CSV tối đa 8 MB.');uploaded=parseCSV(await file.text());$('upload-info').textContent=`${file.name} · ${uploaded.length} dòng · ${'month' in uploaded[0]?'dữ liệu tháng':'đặc trưng theo vụ'}`;if(!('month' in uploaded[0])){const first=uploaded[0];if(provinces.some(p=>String(p.adm1_code)===String(Number(first.adm1_code))))$('province').value=String(Number(first.adm1_code));if([...$('year').options].some(o=>+o.value===+first.nam))$('year').value=first.nam;if(SEASONS[first.mua_vu])$('season').value=first.mua_vu;}clearResult();updateForm();}catch(error){uploaded=[];$('form-message').textContent=error.message;}};$('download-template').onclick=()=>{const row={};for(const name of model.feature_names)row[name]=history[0][name];const s=selection();row.adm1_code=s.code;row.nam=s.year;row.mua_vu=s.season;for(const k of model.schema.numeric_features)if(k!=='nam')row[k]=null;download('lua_lab_mau_dac_trung.csv',makeCSV([row]));};$('download-result').onclick=()=>{if(!lastResult)return;const {row,value,source}=lastResult;download(`lua_lab_${row.adm1_code}_${row.nam}_${row.mua_vu}.csv`,makeCSV([{...row,predicted_t_ha:value,model:model.name,source,model_sha256:model.artifact_sha256,estimated_at:new Date().toISOString()}]));};init();
